import{_ as n,o,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Hammer (Day 2) - RBD: Copy-on-Read for Clones in Kernel RBD Clients","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - RBD: Copy-on-Read for Clones in Kernel RBD Clients","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["RBD","Ceph","Distributed Storage","Copy","on","Read","Kernel Client"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_RBD_-_Copy-on-Read_for_Clones_in_Kernel_RBD_Clients.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_RBD_-_Copy-on-Read_for_Clones_in_Kernel_RBD_Clients.md","lastUpdated":1780459816000}'),_={name:"posts/2014/CDS_Hammer_Day_2_-_RBD_-_Copy-on-Read_for_Clones_in_Kernel_RBD_Clients.md"};function i(r,e,s,a,p,D){return o(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： RBD（RADOS Block Device）克隆的“读复制”功能开发讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Minchen, Lee Wong, Josh 以及其他未提及的成员</p><p><strong>会议内容</strong>：</p><p><strong>1. RBD克隆的“读复制”功能概述</strong></p><ul><li>Minchen 和 Lee Wong 介绍了 RBD 克隆在内核 RBD 客户端的“读复制”功能。</li><li>该功能通过客户端复制操作，减少与 RADOS 的交互，提高读取效率。</li><li>客户端在读取克隆对象前，会从父对象中读取数据，并将数据缓存到内存中。</li></ul><p><strong>2. 对象映射功能</strong></p><ul><li>对象映射功能有助于优化复制过程，通过告知客户端对象是否存在，避免额外往返操作。</li><li>该功能与复制功能独立，可同时使用。</li></ul><p><strong>3. 核心实现与用户空间实现</strong></p><ul><li>用户空间实现尚未合并，需提交构建请求供审查。</li><li>核心实现需等待用户空间实现合并后才能提交。</li></ul><p><strong>4. 问题与讨论</strong></p><ul><li>讨论了等待请求完成的问题，需要进一步考虑。</li><li>需要分离读写请求的处理，以便在错误和刷新时停止 I/O，无需取消映射图像。</li><li>对象映射功能和复制功能具有不同目的，可同时使用。</li></ul><p><strong>5. 行动计划</strong></p><ul><li>Minchen 和 Lee Wong 继续开发“读复制”功能。</li><li>Josh 将提交用户空间实现请求，以便合并。</li><li>核心实现团队将等待用户空间实现合并后，再提交核心实现代码。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提及 Chrome 浏览器误报 ad.sap.com 为钓鱼网站的问题，但已确认该警告为误报。</li><li>讨论了 RBD 的其他功能，如“高级条带化”，但未涉及具体细节。</li></ul>',17)])])}const R=n(_,[["render",i]]);export{d as __pageData,R as default};
